import pandas as pd
import numpy as np


def clean(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()

    def parse_income(v):
        # Handle missing / non-string values
        if v is None:
            return np.nan
        if isinstance(v, (int, float, np.integer, np.floating)) and not isinstance(v, bool):
            return np.nan if pd.isna(v) else float(v)
        if not isinstance(v, str):
            return np.nan

        s = v.strip().replace('$', '').replace(',', '')
        if s == '' or s.lower() in ('n/a', 'na', 'nan', 'none', 'null'):
            return np.nan

        mult = 1.0
        last = s[-1].lower()
        if last == 'k':
            mult = 1_000.0
            s = s[:-1].strip()
        elif last == 'm':
            mult = 1_000_000.0
            s = s[:-1].strip()

        try:
            return float(s) * mult
        except ValueError:
            return np.nan

    out['income'] = out['income'].map(parse_income).astype(float)

    def clean_city(v):
        if v is None:
            return v
        if isinstance(v, float) and pd.isna(v):
            return v
        if not isinstance(v, str):
            return v
        # Strip outer whitespace, collapse repeated inner whitespace to one space
        s = ' '.join(v.split())
        # Title case
        return s.title()

    out['city'] = out['city'].map(clean_city)

    return out[['age', 'income', 'city']]

